parameters.text:
=이전 대화 맥락과 아래의 최신 사용자 메시지를 종합하여 의도를 분류하고 파라미터를 추출하세요.

사용자 메시지:
{{ $json.chatInput }}
---
오늘 날짜: {{ $now.format('yyyy-MM-dd ccc') }}

parameters.inputSchema:
{
  "name": "financial_router_response",
  "strict": true,
  "schema": {
    "$schema": "http://json-schema.org/draft-07/schema#",
    "type": "object",
    "anyOf": [
      {
        "type": "object",
        "properties": {
          "intent": { "type": "string", "const": "expense_add", "description": "가계부 Agent 의 사용자 입력 의도 분류" },
          "params": {
            "type": "object",
            "description": "의도별 추출 파라미터",
            "properties": {
              "amount": { "type": ["number", "null"], "description": "지출/수입 금액 (숫자만)" },
              "type": { "type": "string", "enum": ["expense", "income"], "description": "지출 또는 수입 구분" },
              "category_raw": { "type": ["string", "null"], "description": "사용자가 말한 카테고리 텍스트" },
              "memo": { "type": ["string", "null"], "description": "금액/카테고리/날짜/태그를 제외한 나머지 설명" },
              "date": { "type": ["string", "null"], "description": "YYYY-MM-DD 형식의 날짜" },
              "tags": {
                "type": "array",
                "items": { "type": "string" },
                "description": "'#'을 제외한 태그 목록"
              }
            },
            "required": ["amount", "type", "category_raw", "memo", "date", "tags"],
            "additionalProperties": false
          }
        },
        "required": ["intent", "params"],
        "additionalProperties": false
      },
      {
        "type": "object",
        "properties": {
          "intent": { "type": "string", "const": "query" },
          "params": {
            "type": "object",
            "properties": {
              "raw_question": { "type": "string", "description": "사용자 질의 원문" }
            },
            "required": ["raw_question"],
            "additionalProperties": false
          }
        },
        "required": ["intent", "params"],
        "additionalProperties": false
      },
      {
        "type": "object",
        "properties": {
          "intent": { "type": "string", "const": "update_delete" },
          "params": {
            "type": "object",
            "properties": {
              "action": { "type": "string", "enum": ["update", "delete"] },
              "target_raw": { "type": "string", "description": "대상을 가리키는 사용자 표현" },
              "new_amount": { "type": ["number", "null"], "description": "수정 시 변경할 금액 (삭제시 null)" }
            },
            "required": ["action", "target_raw", "new_amount"],
            "additionalProperties": false
          }
        },
        "required": ["intent", "params"],
        "additionalProperties": false
      },
      {
        "type": "object",
        "properties": {
          "intent": { "type": "string", "const": "category_manage" },
          "params": {
            "type": "object",
            "properties": {
              "action": { "type": "string", "enum": ["add", "set_budget"] },
              "category_name": { "type": "string", "description": "카테고리명" },
              "budget": { "type": ["number", "null"], "description": "설정 예산 금액" }
            },
            "required": ["action", "category_name", "budget"],
            "additionalProperties": false
          }
        },
        "required": ["intent", "params"],
        "additionalProperties": false
      },
      {
        "type": "object",
        "properties": {
          "intent": { "type": "string", "const": "recurring_add" },
          "params": {
            "type": "object",
            "properties": {
              "name": { "type": "string", "description": "정기 결제 항목명" },
              "amount": { "type": "number", "description": "정기 결제 금액" },
              "category_raw": { "type": ["string", "null"], "description": "카테고리 텍스트" },
              "billing_day": { "type": "integer", "minimum": 1, "maximum": 31, "description": "매월 결제일 (1~31)" },
              "start_date": { "type": "string", "description": "시작일 (YYYY-MM-DD)" }
            },
            "required": ["name", "amount", "category_raw", "billing_day", "start_date"],
            "additionalProperties": false
          }
        },
        "required": ["intent", "params"],
        "additionalProperties": false
      },
      {
        "type": "object",
        "properties": {
          "intent": { "type": "string", "const": "unknown" },
          "params": {
            "type": "object",
            "properties": {
              "output_msg": { "type": "string", "description": "부족한 정보 안내 또는 정중한 거절 메시지" }
            },
            "required": ["output_msg"],
            "additionalProperties": false
          }
        },
        "required": ["intent", "params"],
        "additionalProperties": false
      }
    ]
  }
}
